.min88-photo-tour{
max-width:1200px;
margin:30px auto 18px;
overflow:hidden;
border-radius:22px;
}
.min88-photo-tour__track{
display:grid;
grid-template-columns:2fr 1fr 1fr;
grid-template-rows:220px 220px;
gap:6px;
}
.min88-photo-tour__item{
position:relative;
overflow:hidden;
background:#f3f3f3;
cursor:pointer;
}
.min88-photo-tour__main{
grid-row:1 / span 2;
}
.min88-photo-tour__extra{
display:none;
}
.min88-photo-tour.is-expanded{
overflow:visible;
border-radius:0;
}
.min88-photo-tour.is-expanded .min88-photo-tour__track{
grid-template-columns:repeat(4, 1fr);
grid-template-rows:none;
}
.min88-photo-tour.is-expanded .min88-photo-tour__item{
height:210px;
border-radius:16px;
}
.min88-photo-tour.is-expanded .min88-photo-tour__main{
grid-row:auto;
}
.min88-photo-tour.is-expanded .min88-photo-tour__extra{
display:block;
}
.min88-photo-tour__item img{
width:100%;
height:100%;
display:block;
object-fit:cover;
transition:filter .25s ease, transform .25s ease;
}
@media (min-width:769px){
.min88-photo-tour__item:hover img{
filter:brightness(0.88);
transform:scale(1.02);
}
}
.min88-photo-tour-more{
display:block;
margin:0 auto 50px;
padding:12px 24px;
border:none;
border-radius:999px;
background:#f1f1f1;
color:#111;
font-size:15px;
font-weight:700;
cursor:pointer;
}
.min88-photo-tour-more:hover{
background:#e5e5e5;
}
@media (max-width:768px){
.min88-photo-tour{
width:calc(100% - 6px);
height:68vw;
max-height:420px;
min-height:230px;
max-width:none;
margin:18px auto 24px;
overflow-x:auto;
overflow-y:hidden;
border-radius:0;
scroll-snap-type:x mandatory;
-webkit-overflow-scrolling:touch;
scrollbar-width:none;
}
.min88-photo-tour::-webkit-scrollbar{
display:none;
}
.min88-photo-tour__track{
display:flex;
gap:14px;
height:100%;
}
.min88-photo-tour__item,
.min88-photo-tour__main,
.min88-photo-tour.is-expanded .min88-photo-tour__item{
flex:0 0 100%;
width:100%;
height:100%;
border-radius:22px;
grid-row:auto;
scroll-snap-align:start;
box-shadow:0 8px 24px rgba(0,0,0,.08);
}
.min88-photo-tour__extra{
display:block;
}
.min88-photo-tour__item img{
transition:none;
}
.min88-photo-tour__item::after{
content:attr(data-count);
position:absolute;
right:14px;
bottom:14px;
padding:6px 12px;
border-radius:10px;
background:rgba(0,0,0,.68);
color:#fff;
font-size:15px;
font-weight:700;
z-index:10;
}
.min88-photo-tour-more{
display:none;
}
}
.min88-photo-tour-modal{
position:fixed;
inset:0;
z-index:999999;
display:none;
align-items:center;
justify-content:center;
background:rgba(0,0,0,.82);
padding:5vh 5vw;
box-sizing:border-box;
}
.min88-photo-tour-modal.is-active{
display:flex;
}
.min88-photo-tour-modal img{
max-width:90vw;
max-height:90vh;
width:auto;
height:auto;
object-fit:contain;
display:block;
border-radius:14px;
}
.min88-photo-tour-modal__close{
position:absolute;
top:18px;
right:22px;
width:44px;
height:44px;
border:none;
border-radius:50%;
background:rgba(255,255,255,.92);
font-size:30px;
cursor:pointer;
}
(function(){
function init(){
const gallery = document.querySelector('.min88-photo-tour');
if (!gallery) return;
const items = Array.from(gallery.querySelectorAll('.min88-photo-tour__item'));
const total = items.length;
const moreBtn = document.querySelector('.min88-photo-tour-more');
let touchStartX = 0;
let touchMoved = false;
items.forEach(function(item, index){
item.setAttribute('data-count', (index + 1) + ' / ' + total);
});
if (moreBtn) {
moreBtn.textContent = 'View all photos (' + total + ')';
moreBtn.addEventListener('click', function(){
const expanded = gallery.classList.toggle('is-expanded');
moreBtn.textContent = expanded
? 'Close photos'
: 'View all photos (' + total + ')';
});
}
gallery.addEventListener('touchstart', function(e){
touchStartX = e.touches[0].clientX;
touchMoved = false;
}, { passive:true });
gallery.addEventListener('touchmove', function(e){
const diff = Math.abs(e.touches[0].clientX - touchStartX);
if (diff > 8) touchMoved = true;
}, { passive:true });
let modal = document.querySelector('.min88-photo-tour-modal');
if (!modal) {
modal = document.createElement('div');
modal.className = 'min88-photo-tour-modal';
modal.innerHTML =
'<button type="button" class="min88-photo-tour-modal__close">×</button>' +
'<img decoding="async" src="" alt="">';
document.body.appendChild(modal);
}
const modalImg = modal.querySelector('img');
const closeBtn = modal.querySelector('.min88-photo-tour-modal__close');
items.forEach(function(item){
item.addEventListener('click', function(){
if (touchMoved) return;
const img = item.querySelector('img');
if (!img) return;
modalImg.src = img.currentSrc || img.src;
modalImg.alt = img.alt || '';
modal.classList.add('is-active');
document.body.style.overflow = 'hidden';
});
});
function closeModal(){
modal.classList.remove('is-active');
modalImg.src = '';
document.body.style.overflow = '';
}
closeBtn.addEventListener('click', closeModal);
modal.addEventListener('click', function(e){
if (e.target === modal) closeModal();
});
}
setTimeout(init, 300);
})();
