/* ===== ラッパ（左右余白） ===== */
.min88-inn-review-wrap {
max-width: 1080px;
margin: 0 auto;
padding: 0 15px;
box-sizing: border-box;
}
/* ===== 本体ボックス ===== */
.min88-inn-review {
margin: 28px 0 20px;
padding: 30px 30px 6px 40px;
border-radius: 13px;
border: 1px solid #efefef;
background: #fcfcfc;
box-shadow: 0 10px 13px rgba(0,0,0,0.15);
position: relative;
box-sizing: border-box;
}
/* “ アイコン（紹介文とテイスト合わせ） */
.min88-inn-review__icon {
position: absolute;
top: 10px;
left: 20px;
font-size: 90px;
line-height: 1;
color: #ff2d9a; /* 紹介文と同じピンク */
pointer-events: none;
font-weight: 700;
}
/* タイトル */
.min88-inn-review h3.min88-inn-review__title {
margin: 12px 0 14px;
font-size: 18px;
line-height: 1.6;
font-weight: 500;
color: #222222 !important;
}
/* 要約本文 */
.min88-inn-review p.min88-inn-review__text {
margin: 0 0 10px;
font-size: 14px;
line-height: 1.8;
color: #444444 !important;
}
/* ===== フッター（下線＋参照元） ===== */
.min88-inn-review__footer {
margin-top: 6px;
}
/* ★ 線を太く（2px）＆少し濃くする */
.min88-inn-review__divider {
margin: 12px 0 12px;
height: 1.5px; /* ← 1px → 2px */
width: 100%;
background: linear-gradient(
to right,
rgba(0,0,0,0.12),
rgba(0,0,0,0.06),
rgba(0,0,0,0.15)
);
}
/* ★ 参照元の下余白を強制的に狭くする */
.min88-inn-review__source {
margin-top: 0 !important;
margin-bottom: 4px !important;
font-size: 11px;
line-height: 1.35 !important; /* ← 行間を狭く */
text-align: right;
color: #999999;
padding: 0 !important; /* ← ブロック余白対策（念のため） */
}
/* ===== スマホ調整 ===== */
@media (max-width: 768px) {
.min88-inn-review-wrap {
padding: 0 3px;
}
.min88-inn-review {
padding: 30px 20px 12px 30px;
}
.min88-inn-review__icon {
top: 16px;
left: 16px;
font-size: 85px;
}
.min88-inn-review h3.min88-inn-review__title {
margin: 10px 0 12px;
font-size: 18px;
}
.min88-inn-review p.min88-inn-review__text {
font-size: 14px;
}
.min88-inn-review__source {
font-size: 11.5px;
line-height: 1.35 !important; /* ← スマホ時の行間を狭く */
margin-bottom: 2px !important; /* ← さらに下の余白も詰める */
}
}
.standout-button {
display: block;
width: 250px;
box-sizing: border-box;
text-align: center;
margin: 40px auto;
padding: 0.5rem 1rem;
background-color: #007BFF;
color: white !important;
font-weight: bold;
border: none;
border-radius: 5px;
border-bottom: 7px solid #0056b3;
transition: all 0.1s ease;
text-decoration: none;
}
.standout-button:hover {
background-color: #007BFF;
transform: translateY(4px);
border-bottom: 7px solid transparent;
}
