document.addEventListener("DOMContentLoaded", function () {
const link = document.querySelector(".min88-phone-link");
const msg = document.querySelector(".min88-phone-time-msg");
if (!link || !msg) return;
const lang = document.documentElement.lang || "ja";
let langKey = "ja";
if (lang.startsWith("en")) {
langKey = "en";
} else if (lang.startsWith("zh")) {
langKey = "zh";
}
const textMap = {
ja: {
normal: "☎ 電話で空室確認",
disabled: "☎ 電話対応時間外",
hours: (s, e) => `受付時間 ${s}〜${e}`
},
en: {
normal: "☎ Check by Phone",
disabled: "☎ Outside Call Hours",
hours: (s, e) => `Call hours ${s}–${e}`
},
zh: {
normal: "☎ 電話確認空房",
disabled: "☎ 非電話服務時間",
hours: (s, e) => `服務時間 ${s}–${e}`
}
};
const t = textMap[langKey];
const startHour = 8;
const startMin = 0;
const endHour = 21;
const endMin = 0;
const now = new Date();
const nowMinutes =
now.getHours() * 60 + now.getMinutes();
const startMinutes =
startHour * 60 + startMin;
const endMinutes =
endHour * 60 + endMin;
const format = (h, m) =>
`${h}:${String(m).padStart(2,'0')}`;
const startStr = format(startHour, startMin);
const endStr = format(endHour, endMin);
if (
nowMinutes < startMinutes ||
nowMinutes >= endMinutes
) {
link.classList.add("is-disabled");
link.onclick = function(e){
e.preventDefault();
};
link.textContent = t.disabled;
msg.style.display = "block";
msg.textContent =
t.hours(startStr, endStr);
} else {
link.classList.remove("is-disabled");
link.textContent = t.normal;
msg.style.display = "none";
}
});
