.min88-photo-tour{
max-width:1200px;
margin:30px auto 18px;
overflow:hidden;
border-radius:22px;
}
.min88-photo-tour__track{
display:grid;
grid-template-columns:2fr 1fr 1fr;
grid-template-rows:220px 220px;
gap:6px;
}
.min88-photo-tour__item{
position:relative;
overflow:hidden;
background:#f3f3f3;
cursor:pointer;
}
.min88-photo-tour__main{
grid-row:1 / span 2;
}
.min88-photo-tour__extra{
display:none;
}
.min88-photo-tour.is-expanded{
overflow:visible;
border-radius:0;
}
.min88-photo-tour.is-expanded .min88-photo-tour__track{
grid-template-columns:repeat(4, 1fr);
grid-template-rows:none;
}
.min88-photo-tour.is-expanded .min88-photo-tour__item{
height:210px;
border-radius:16px;
}
.min88-photo-tour.is-expanded .min88-photo-tour__main{
grid-row:auto;
}
.min88-photo-tour.is-expanded .min88-photo-tour__extra{
display:block;
}
.min88-photo-tour__item img{
width:100%;
height:100%;
display:block;
object-fit:cover;
transition:filter .25s ease, transform .25s ease;
}
@media (min-width:769px){
.min88-photo-tour__item:hover img{
filter:brightness(0.88);
transform:scale(1.02);
}
}
.min88-photo-tour-more{
display:block;
margin:0 auto 50px;
padding:12px 24px;
border:none;
border-radius:999px;
background:#f1f1f1;
color:#111;
font-size:15px;
font-weight:700;
cursor:pointer;
}
.min88-photo-tour-more:hover{
background:#e5e5e5;
}
@media (max-width:768px){
.min88-photo-tour{
width:calc(100% - 6px);
height:68vw;
max-height:420px;
min-height:230px;
max-width:none;
margin:18px auto 24px;
overflow-x:auto;
overflow-y:hidden;
border-radius:0;
scroll-snap-type:x mandatory;
-webkit-overflow-scrolling:touch;
scrollbar-width:none;
}
.min88-photo-tour::-webkit-scrollbar{
display:none;
}
.min88-photo-tour__track{
