.min88-photo-tour{
max-width:1200px;
margin:30px auto 18px;
overflow:hidden;
border-radius:22px;
}
.min88-photo-tour__track{
display:grid;
grid-template-columns:2fr 1fr 1fr;
grid-template-rows:220px 220px;
gap:6px;
}
.min88-photo-tour__item{
position:relative;
overflow:hidden;
background:#f3f3f3;
cursor:pointer;
}
.min88-photo-tour__main{
grid-row:1 / span 2;
}
.min88-photo-tour__extra{
display:none;
}
.min88-photo-tour.is-expanded{
overflow:visible;
border-radius:0;
}
.min88-photo-tour.is-expanded .min88-photo-tour__track{
grid-template-columns:repeat(4, 1fr);
grid-template-rows:none;
}
.min88-photo-tour.is-expanded .min88-photo-tour__item{
height:210px;
border-radius:16px;
}
.min88-photo-tour.is-expanded .min88-photo-tour__main{
grid-row:auto;
}
.min88-photo-tour.is-expanded .min88-photo-tour__extra{
display:block;
}
.min88-photo-tour__item img{
width:100%;
height:100%;
display:block;
object-fit:cover;
