(function(){
function init(){
const gallery = document.querySelector('.min88-photo-tour');
if (!gallery) return;
const items = Array.from(gallery.querySelectorAll('.min88-photo-tour__item'));
const total = items.length;
const moreBtn = document.querySelector('.min88-photo-tour-more');
let touchStartX = 0;
let touchMoved = false;
items.forEach(function(item, index){
item.setAttribute('data-count', (index + 1) + ' / ' + total);
});
if (moreBtn) {
moreBtn.textContent = 'View all photos (' + total + ')';
moreBtn.addEventListener('click', function(){
const expanded = gallery.classList.toggle('is-expanded');
moreBtn.textContent = expanded
? 'Close photos'
: 'View all photos (' + total + ')';
});
}
gallery.addEventListener('touchstart', function(e){
touchStartX = e.touches[0].clientX;
touchMoved = false;
}, { passive:true });
gallery.addEventListener('touchmove', function(e){
const diff = Math.abs(e.touches[0].clientX - touchStartX);
if (diff > 8) touchMoved = true;
}, { passive:true });
let modal = document.querySelector('.min88-photo-tour-modal');
if (!modal) {
modal = document.createElement('div');
modal.className = 'min88-photo-tour-modal';
modal.innerHTML =
'<button type="button" class="min88-photo-tour-modal__close">×</button>' +
'<img decoding="async" src="" alt="">';
document.body.appendChild(modal);
}
const modalImg = modal.querySelector('img');
const closeBtn = modal.querySelector('.min88-photo-tour-modal__close');
items.forEach(function(item){
item.addEventListener('click', function(){
if (touchMoved) return;
const img = item.querySelector('img');
if (!img) return;
modalImg.src = img.currentSrc || img.src;
modalImg.alt = img.alt || '';
modal.classList.add('is-active');
document.body.style.overflow = 'hidden';
});
});
function closeModal(){
modal.classList.remove('is-active');
modalImg.src = '';
document.body.style.overflow = '';
}
closeBtn.addEventListener('click', closeModal);
modal.addEventListener('click', function(e){
if (e.target === modal) closeModal();
});
}
setTimeout(init, 300);
})();
